"""Blog (English only), generated by build.py.

To add a post: put its body (HTML, starting below the title) in scripts/blog/<slug>.html,
its images in docs/blog/<slug>/, and add an entry to data/blog.json (newest first).
scripts/sync_blog.py does all three for the articles written in BabyLoveGrowth.
Then run `python3 scripts/build.py`: it writes docs/blog/ and adds the pages to the sitemap.
"""
import datetime
import html
import json
from pathlib import Path

import pages

HERE = Path(__file__).resolve().parent
SITE = pages.SITE

# Newest first. scripts/sync_blog.py adds the BabyLoveGrowth articles here.
POSTS = json.loads((HERE.parent / "data" / "blog.json").read_text())


CSS = """.doc h2{scroll-margin-top:80px}.doc ol{margin:10px 0 0 22px}.doc ol li{padding-left:4px}
.doc figure{margin:28px 0 0}.doc figure img,.cover img{display:block;width:100%;height:auto;border-radius:14px;border:1px solid var(--line)}
.cover{margin:26px 0 8px}.byline{color:var(--faint);font-size:14px;margin-top:14px}
.cta{margin-top:44px;padding:22px 24px;border:1px solid var(--line);border-radius:14px;background:rgba(243,234,216,.04)}
.cta p{margin:0}.cta a.btn{display:inline-block;margin-top:14px;background:var(--lamp,#ffcf70);color:#1b2147;font-weight:600;
text-decoration:none;padding:10px 18px;border-radius:10px}.cta a.btn:hover{color:#1b2147;filter:brightness(1.05)}
.posts{list-style:none;margin:0!important;padding:0}.posts li{border-top:1px solid var(--line);padding:22px 0;margin:0!important;max-width:none}
.posts li:first-child{border-top:0;padding-top:0}.posts a{text-decoration:none!important;color:var(--ink);font-family:var(--serif);font-size:24px;line-height:1.25}
.doc table{width:100%;border-collapse:collapse;margin-top:18px;font-size:15px}.doc th,.doc td{text-align:left;vertical-align:top;padding:10px 12px;border-bottom:1px solid var(--line)}
.doc th{color:var(--ink);font-weight:600;border-bottom-color:var(--line2)}.doc .tbl{overflow-x:auto}
.posts a:hover{text-decoration:underline!important}.posts p{margin-top:6px}.posts .when{color:var(--faint);font-size:14px;margin-top:6px}
"""


def _day(iso: str) -> str:
    d = datetime.date.fromisoformat(iso)
    return d.strftime("%B ") + str(d.day) + d.strftime(", %Y")


def _shell(path: str, title: str, desc: str, head_extra: str, header: str, body: str) -> str:
    return f"""<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>{html.escape(title, quote=False)}</title>
<meta name="description" content="{html.escape(desc)}">
<meta name="theme-color" content="#1b2147">
<link rel="icon" href="/favicon.ico" sizes="48x48">
<link rel="icon" href="/favicon-96.png?v=2" type="image/png" sizes="96x96">
<link rel="icon" href="/logo.svg?v=2" type="image/svg+xml">
<link rel="apple-touch-icon" href="/apple-touch-icon.png?v=2">
<link rel="canonical" href="{SITE}{path}">
<link rel="alternate" type="application/rss+xml" title="Dormer blog" href="{SITE}/blog/feed.xml">
{head_extra}{pages.FONT_HEAD}
<style>
{pages._css()}{CSS}</style>
</head>
<body>
<nav><div class="wrap">
  <a class="brand" href="/" aria-label="Dormer"><img src="/icon-64.png?v=2" alt="Dormer logo" width="32" height="32"><span>Dormer</span></a>
  <span class="sp"></span>
  <a class="navlink" href="/blog/">Blog</a>
  <a class="navlink" href="/">Home</a>
</div></nav>
<header><div class="wrap narrow">
{header}
</div></header>
<main class="wrap narrow doc">
<section>
{body}
</section>
</main>
<footer><div class="wrap">
  <span>© 2026 Dormer</span>
  <a href="/">Back to Dormer</a>
  <a href="/blog/">Blog</a>
  <a href="/compare/">Compare notch apps</a>
  <a href="/changelog/">Versions</a>
  <a href="/privacy/">Privacy</a>
  <a href="https://github.com/Zerdoxy741/dormer">GitHub</a>
</div></footer>
</body>
</html>
"""


def _post(p: dict) -> str:
    path = f"/blog/{p['slug']}/"
    img = f"{SITE}/blog/{p['slug']}/{p['cover']}"
    w, h = p["cover_size"]
    body = (HERE / "blog" / f"{p['slug']}.html").read_text().strip()
    ld = [{
        "@context": "https://schema.org", "@type": "BlogPosting", "headline": p["title"], "description": p["desc"],
        "image": img, "datePublished": p["date"], "dateModified": p["date"], "inLanguage": "en",
        "mainEntityOfPage": SITE + path, "author": {"@type": "Organization", "name": "Dormer", "url": SITE + "/"},
        "publisher": {"@type": "Organization", "name": "Dormer", "logo": {"@type": "ImageObject", "url": SITE + "/icon.png"}},
    }]
    head = (f'<meta property="og:type" content="article">\n<meta property="og:title" content="{html.escape(p["title"])}">\n'
            f'<meta property="og:description" content="{html.escape(p["desc"])}">\n<meta property="og:image" content="{img}">\n'
            f'<meta property="og:url" content="{SITE}{path}">\n<meta property="og:site_name" content="Dormer">\n'
            f'<meta property="article:published_time" content="{p["date"]}">\n<meta name="twitter:card" content="summary_large_image">\n'
            f'<script type="application/ld+json">{json.dumps(ld, ensure_ascii=False)}</script>\n')
    header = (f'  <h1>{html.escape(p["title"], quote=False)}</h1>\n'
              f'  <p class="byline">By the Dormer team · <time datetime="{p["date"]}">{_day(p["date"])}</time></p>\n'
              f'  <figure class="cover"><img src="/blog/{p["slug"]}/{p["cover"]}" alt="{html.escape(p["cover_alt"])}" '
              f'width="{w}" height="{h}" fetchpriority="high"></figure>')
    cta = ('<div class="cta"><p><strong>Try Dormer free.</strong> For MacBooks with a notch, on macOS 14.2 or later. '
           'Every download includes 14 days of Dormer Pro. No account, no card.</p>'
           '<a class="btn" href="/">Get Dormer</a></div>')
    return _shell(path, f"{p['title']} · Dormer", p["desc"], head, header, body + "\n\n" + cta)


def _index() -> str:
    items = "\n".join(
        f'<li><a href="/blog/{p["slug"]}/">{html.escape(p["title"], quote=False)}</a>'
        f'<p>{html.escape(p["desc"], quote=False)}</p><p class="when">{_day(p["date"])}</p></li>' for p in POSTS)
    header = ('  <h1>Blog</h1>\n  <p class="lead">Guides for getting more out of your Mac and its notch.</p>')
    return _shell("/blog/", "Blog · Dormer", "Guides for getting more out of your Mac and its notch, from the makers of Dormer.",
                  "", header, f'<ul class="posts">\n{items}\n</ul>')


def _feed() -> str:
    items = "".join(
        f"<item><title>{html.escape(p['title'])}</title><link>{SITE}/blog/{p['slug']}/</link>"
        f"<guid>{SITE}/blog/{p['slug']}/</guid><description>{html.escape(p['desc'])}</description>"
        f"<pubDate>{datetime.date.fromisoformat(p['date']).strftime('%a, %d %b %Y')} 08:00:00 +0000</pubDate></item>"
        for p in POSTS)
    return (f'<?xml version="1.0" encoding="UTF-8"?>\n<rss version="2.0"><channel><title>Dormer blog</title>'
            f'<link>{SITE}/blog/</link><description>Guides from the makers of Dormer.</description><language>en</language>'
            f'{items}</channel></rss>\n')


def urls():
    """(path, lastmod) for the sitemap."""
    out = [("/blog/", POSTS[0]["date"])] if POSTS else []
    return out + [(f"/blog/{p['slug']}/", p["date"]) for p in POSTS]


def build(write):
    write("blog/index.html", _index())
    write("blog/feed.xml", _feed())
    for p in POSTS:
        write(f"blog/{p['slug']}/index.html", _post(p))
